const settings = {
  injectFailure: true,
  failureRow: 102,
  failureStage: 'upload', // download, transcribe, plan, images, captions, render or upload
  duration: 10,
  minimumWordsForNewClip: 3,
  fps: 30,
  width: 1080,
  height: 1920,
};
if (!['download', 'transcribe', 'plan', 'images', 'captions', 'render', 'upload'].includes(settings.failureStage)) {
  throw new Error('Choose a supported failureStage');
}
return [{json: {simulated: true, settings}}];

const settings = $input.first().json.settings;
const images = ['https://images.example.invalid/sky.jpg',
                'https://images.example.invalid/forest.jpg',
                'https://images.example.invalid/sea.jpg', 'https://images.example.invalid/mountain.jpg'];
const jobs = [
  {row: 101, id: 'morning', status: 'NOT_PROCESSED'},
  {row: 102, id: 'evening', status: 'NOT_PROCESSED'},
  {row: 103, id: 'already-finished', status: 'DONE'},
  {row: 104, id: 'after-failure', status: 'NOT_PROCESSED'},
];
return jobs.map(job => ({json: {simulated: true, settings, images,
  job: {...job, voice_link: 'https://audio.example.invalid/' + job.row + '.wav'},
  checkpoints: {}, history: [{stage: 'read_snapshot', result: 'simulated'}]},
  pairedItem: {item: 0}}));

return $input.all().map((item, index) => ({json: {...item.json, outcome: 'skipped',
  history: [...item.json.history, {stage: 'skip', result: item.json.job.status}]},
  pairedItem: {item: index}}));

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  const name = 'row-' + data.job.row + '-demo';
  data.workspace = {work: 'temp/' + name, audio: 'buffer/voiceovers/' + name + '.audio',
                    images: 'temp/' + name + '/images', output: 'output/' + name + '.mp4'};
  data.job.status = 'PROCESSING';
  data.history.push({stage: 'PROCESSING', result: 'simulated'});
  return {json: data, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  if (!data.error) {
    try {
      if (data.settings.injectFailure && data.job.row === data.settings.failureRow &&
          data.settings.failureStage === "download") {
        throw new Error('Injected demo failure at ' + "download");
      }
      data.audio = {path: data.workspace.audio, duration: data.settings.duration,
              simulated: true, file_exists: false};
if (!Number.isFinite(data.audio.duration) || data.audio.duration <= 0) throw new Error('Invalid duration');
      data.history.push({stage: "download", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "download", message: String(error.message || error)};
      data.history.push({stage: "download", result: 'failed', message: data.error.message});
    }
  }
  return {json: data, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  if (!data.error) {
    try {
      if (data.settings.injectFailure && data.job.row === data.settings.failureRow &&
