      }
      data.transcript = {text: 'Morning light fills the sky. Breathe. We begin again.', words: [
  {text: 'Morning', start: 0.4, end: 0.8}, {text: 'light', start: 1, end: 1.3},
  {text: 'fills', start: 1.4, end: 1.6}, {text: 'the', start: 1.7, end: 1.9},
  {text: 'sky.', start: 2, end: 2.3}, {text: 'Breathe.', start: 3, end: 3.4},
  {text: 'We', start: 5, end: 5.3}, {text: 'begin', start: 5.4, end: 5.7},
  {text: 'again.', start: 5.9, end: 6.3}], simulated: true};
if (data.audio.duration < 6.3) throw new Error('Demo transcript needs at least 6.3 seconds of audio');
data.checkpoints['transcript.json'] = data.transcript;
      data.history.push({stage: "transcribe", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "transcribe", message: String(error.message || error)};
      data.history.push({stage: "transcribe", result: 'failed', message: data.error.message});
    }
