  return {json: data, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  if (!data.error) {
    try {
      if (data.settings.injectFailure && data.job.row === data.settings.failureRow &&
          data.settings.failureStage === "plan") {
        throw new Error('Injected demo failure at ' + "plan");
      }
      const sentences = [];
let current = [];
for (const word of data.transcript.words) {
  current.push(word);
  if (/[.!?。！？]["'”’»)]*$/.test(word.text)) {
    sentences.push({words: current, start: current[0].start});
    current = [];
  }
}
for (let i = 0; i < current.length; i += 20) {
  const words = current.slice(i, i + 20);
  sentences.push({words, start: words[0].start});
}
const duration = data.audio.duration;
const starts = [0, ...new Set(sentences.filter(sentence =>
  sentence.words.length >= data.settings.minimumWordsForNewClip && sentence.start > 0 &&
  sentence.start < duration).map(sentence => sentence.start))].sort((a, b) => a - b);
if (!data.images.length) throw new Error('No images');
data.plan = {duration, footage: starts.map((start, index) => ({
  start, end: starts[index + 1] ?? duration,
  source: {path: data.images[index % data.images.length], kind: 'image'}, offset: 0,
})), captions: sentences.map((sentence, index) => ({
  sentence: {...sentence, text: sentence.words.map(word => word.text).join(' ')},
  end: sentences[index + 1]?.start ?? duration,
}))};
// Deliberately deterministic for inspection. Python uses random selection with an optional seed.
      data.history.push({stage: "plan", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "plan", message: String(error.message || error)};
      data.history.push({stage: "plan", result: 'failed', message: data.error.message});
    }
  }
  return {json: data, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  if (!data.error) {
