      if (data.settings.injectFailure && data.job.row === data.settings.failureRow &&
          data.settings.failureStage === "images") {
        throw new Error('Injected demo failure at ' + "images");
      }
      const urls = [...new Set(data.plan.footage.map(interval => interval.source.path))];
data.selected_images = urls.map((url, index) => ({url,
  path: data.workspace.images + '/image-' + String(index + 1).padStart(3, '0') + '.jpg',
  decoded: 'simulated', file_exists: false}));
const local = new Map(data.selected_images.map(image => [image.url, image.path]));
data.plan.footage = data.plan.footage.map(interval => ({...interval,
  source: {...interval.source, path: local.get(interval.source.path)}}));
      data.history.push({stage: "images", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "images", message: String(error.message || error)};
      data.history.push({stage: "images", result: 'failed', message: data.error.message});
    }
  }
  return {json: data, pairedItem: {item: index}};
});

