      data.caption_events = data.plan.captions.flatMap(caption => caption.sentence.words.map((word, index, words) => ({
  start: word.start, end: words[index + 1]?.start ?? caption.end,
  visible_text: words.slice(0, index + 1).map(entry => entry.text).join(' '),
  reserved_layout_text: caption.sentence.text,
})));
data.caption_style = {font: 'Special Elite', progressive: true, persist_during_silence: true};
      data.history.push({stage: "captions", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "captions", message: String(error.message || error)};
      data.history.push({stage: "captions", result: 'failed', message: data.error.message});
    }
