return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  if (!data.error) {
    try {
      if (data.settings.injectFailure && data.job.row === data.settings.failureRow &&
          data.settings.failureStage === "render") {
        throw new Error('Injected demo failure at ' + "render");
      }
      let cursor = 0;
for (const interval of data.plan.footage) {
  if (interval.start !== cursor || interval.end <= interval.start) throw new Error('Invalid footage coverage');
  cursor = interval.end;
}
if (cursor !== data.audio.duration) throw new Error('Incomplete footage coverage');
data.rendered = {output: data.workspace.output, duration: data.audio.duration,
  width: data.settings.width, height: data.settings.height, fps: data.settings.fps,
  frames: Math.ceil(data.audio.duration * data.settings.fps), video_codec: 'h264', audio_codec: 'aac',
  simulated: true, file_exists: false};
      data.history.push({stage: "render", result: 'simulated'});
    } catch (error) {
      data.error = {stage: "render", message: String(error.message || error)};
      data.history.push({stage: "render", result: 'failed', message: data.error.message});
    }
  }
  return {json: data, pairedItem: {item: index}};
});

