return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  data.job = {...data.job, status: 'DONE', output_file: data.rendered.output,
    output_url: data.uploaded.url, error: ''};
  data.outcome = 'completed';
  data.history.push({stage: 'DONE', result: 'simulated'});
  data.retention = {audio: true, images: true, output: true, temporary_workspace: false,
                    simulated: true, files_exist: false};
  return {json: data, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const data = JSON.parse(JSON.stringify(item.json));
  const error = data.error?.message ?? 'Upload was not confirmed';
  data.checkpoints['failure.json'] = {row: data.job.row, error,
    output: data.rendered?.output ?? '', uploaded_url: data.uploaded?.url ?? '', audio: data.workspace.audio};
  data.job = {...data.job, status: 'FAILED', output_file: data.rendered?.output ?? '',
    output_url: data.uploaded?.url ?? '', error};
  data.outcome = 'failed';
  data.history.push({stage: 'FAILED', result: 'simulated'});
  data.retention = {temporary_workspace: true, complete_output: Boolean(data.rendered),
                    simulated: true, files_exist: false};
  return {json: data, pairedItem: {item: index}};
});

const jobs = $input.all().map(item => item.json);
return [{json: {simulated: true, files_created: false, external_calls: 0,
  processed: jobs.filter(job => job.outcome !== 'skipped').length,
  completed_this_run: jobs.filter(job => job.outcome === 'completed').length,
  failed_this_run: jobs.filter(job => job.outcome === 'failed').length,
  skipped: jobs.filter(job => job.outcome === 'skipped').length,
  jobs, note: 'All output paths, uploads and status updates are simulated. Import the API runner for real processing.'},
  pairedItem: jobs.map((_, item) => ({item}))}];
